/// <summary>
/// PricingAttribute of table <c>CustTable</c> field CommissionGroup.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, CommissionGroup))]
internal class GUPPricingAttributeCustTableCommissionGroup extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, CommissionGroup);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    CustTable               custTable;
    CommissionCustomerGroup commissionCustomerGroup;

    while select CommissionGroup from custtable
        group by CommissionGroup
        join commissionCustomerGroup
        group by GroupId, Name
        where custTable.CommissionGroup == commissionCustomerGroup.GroupId
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(commissionCustomerGroup.GroupId, commissionCustomerGroup.Name);
        ret.add(valueObject);
    }
    return ret;
}
